import { useMemo } from 'react';
import { useSelector } from 'react-redux';

import { FilterForm } from 'models/Filters';
import { selectPageQuickFiltersForm } from 'redux/slices/filters/selectors';

export const usePageFilterQuickFiltersForm = (pageName: string | null) => {
  const quickForm: FilterForm = useSelector(
    pageName ? selectPageQuickFiltersForm(pageName) : () => ({}),
  ) as FilterForm;

  return useMemo(
    () => ({
      quickForm,
    }),
    [quickForm],
  );
};
